package com.dy.artisan3d.ui.componentimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.interop.UIKitViewimport kotlinx.cinterop.ExperimentalForeignApiimport platform.Foundation.*import platform.UIKit.*@OptIn(ExperimentalForeignApi::class)@Composableactual fun ArtisanHtmlText(    html: String,    modifier: Modifier,    selectable: Boolean,    color: Color) {    // Compose Color -> UIKit UIColor    val uiColor = UIColor(        red = color.red.toDouble(),        green = color.green.toDouble(),        blue = color.blue.toDouble(),        alpha = color.alpha.toDouble()    )    // bodyLarge shrift o'lchami (16.0)    val fontSize = 16.0    UIKitView(        factory = {            UITextView().apply {                isEditable = false                scrollEnabled = false                backgroundColor = UIColor.clearColor                isSelectable = selectable                // Justify - qatorlarni to'ldirib turish                textAlignment = NSTextAlignmentJustified                font = UIFont.systemFontOfSize(fontSize)            }        },        modifier = modifier,        update = { textView ->            val data = NSString.create(string = html).dataUsingEncoding(NSUTF8StringEncoding)            if (data != null) {                val attributedString = NSMutableAttributedString.create(                    data = data,                    options = mapOf(NSDocumentTypeDocumentAttribute to NSHTMLTextDocumentType),                    documentAttributes = null,                    error = null                )                // HTML yuklangandan keyin alignment va rangni qayta o'rnatish shart                val range = NSMakeRange(0u, attributedString!!.length())                val style = NSMutableParagraphStyle().apply {                    alignment = NSTextAlignmentJustified                }                attributedString.addAttribute(NSParagraphStyleAttributeName, style, range)                textView.attributedText = attributedString                textView.textColor = uiColor                // Shrift HTML ichidagi stylelar bilan almashib ketmasligi uchun                textView.font = UIFont.systemFontOfSize(fontSize)            }        }    )}